<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api,put,post,csrf,ApiError,type Profile} from '../api'
const emit=defineEmits<{signedOut:[message:string];updated:[]}>()
const roleNames:Record<string,string>={ADMIN:'系统管理员',EMPLOYEE:'普通员工',MANAGER:'部门主管',BUYER:'采购专员',WAREHOUSE:'仓库管理员'}
const message=ref('')
const profile=ref<Profile|null>(null),name=ref(''),email=ref(''),phone=ref(''),currentPassword=ref(''),newPassword=ref(''),confirm=ref(''),busy=ref(false),error=ref('')
const conflict=ref(false),loading=ref(false)
async function load(preserve=false){if(loading.value)return;loading.value=true;error.value='';try{profile.value=await api('/profile');if(!preserve){name.value=profile.value!.display_name;email.value=profile.value!.email;phone.value=profile.value!.phone}conflict.value=false}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
onMounted(()=>load())
async function save(password=false){if(busy.value||loading.value||(!password&&(!profile.value||conflict.value)))return;busy.value=true;error.value='';message.value='';try{if(password){if(newPassword.value!==confirm.value)throw new Error('两次新密码输入不一致');await post('/profile/password',{currentPassword:currentPassword.value,newPassword:newPassword.value})}else await put('/profile',{name:name.value,email:email.value,phone:phone.value,version:profile.value!.version});currentPassword.value='';newPassword.value='';confirm.value='';if(password){emit('signedOut','密码已更新，请使用新密码登录');void csrf().catch(()=>{})}else{profile.value=await api('/profile');emit('updated');message.value='个人资料已保存，无需重新登录'}}catch(e){error.value=(e as Error).message;conflict.value=e instanceof ApiError&&e.status===409}finally{busy.value=false}}
</script>
<template><div class="feature-grid"><section class="panel feature-panel"><h2>个人资料</h2><p class="muted">姓名和联系方式由你维护，部门与角色由管理员分配。</p><p v-if="loading" class="form-hint" role="status">正在读取个人资料…</p><button v-if="!profile&&!loading" class="btn" @click="load()">重新读取个人资料</button><form v-if="profile" @submit.prevent="save()"><div class="profile-ident"><strong>{{profile.username}}</strong><span>{{profile.department}} · {{roleNames[profile.role]||profile.role}}</span></div><label class="field-block">姓名<input v-model="name" maxlength="64" required/></label><label class="field-block">邮箱<input v-model="email" maxlength="160" type="email"/></label><label class="field-block">联系电话<input v-model="phone" maxlength="32" type="tel"/></label><p class="small-copy muted">保存联系方式后继续使用；密码和权限变更仍会使旧登录失效。</p><button class="btn primary" :disabled="busy||loading||conflict||profile.must_change_password">保存个人资料</button></form></section><section class="panel feature-panel"><h2>修改登录密码</h2><p class="muted">密码至少 8 个字符，修改后所有旧登录失效。</p><form @submit.prevent="save(true)"><label class="field-block">当前密码<input v-model="currentPassword" type="password" autocomplete="current-password" required maxlength="256"/></label><label class="field-block">新密码<input v-model="newPassword" type="password" autocomplete="new-password" minlength="8" maxlength="64" required/></label><label class="field-block">确认新密码<input v-model="confirm" type="password" autocomplete="new-password" minlength="8" maxlength="64" required/></label><button class="btn primary" :disabled="busy">修改密码并退出登录</button></form></section><p v-if="message" class="inline-success">{{message}}</p><p v-if="profile?.must_change_password" class="form-hint">密码已由管理员重置，请先修改密码后使用业务功能。</p><p v-if="error" class="form-error" role="alert">{{error}}</p><button v-if="conflict" class="btn" :disabled="busy||loading" @click="load(true)">读取最新版本并保留输入</button></div></template>
